-- open questions: actual MySQL apply, uploaded-file compatibility, later publication/config/API smoke.
-- Scope: existing DRAFT7 only; 92 qry_json + child modification audit. No DDL/INSERT/DELETE/publish/Case/object writes.
-- Fixed strings only; excludes formula/numeric/period/body values. Whitespace is meaningful.
-- Existing read/write policies are preserved; partial92/99 and INCOMPLETE policies remain unchanged.
-- All affected writers/workers stay stopped and upload.enabled=false. Dedicated connection; no pending transaction.
-- Stop on ANY error: ROLLBACK, then report the first error. Never use --force or override @u_ok.
-- Hex payload avoids SQL-mode/backslash/connection-charset ambiguity; decode from the readable evidence JSON.
-- First run ends in ROLLBACK. Only after PRECHECK_OK / VERIFIED are confirmed, rerun this same file
-- with its final ROLLBACK replaced by COMMIT. Keep a restricted backup of original rows before commit.
USE midb;
SET @u_actor='SYSTEM'; -- Replace with the applying user's login ID if audit policy requires it (1..50 chars).
SET @u_tmplt=7, @u_model='DRAFT_C_STRUCTURE', @u_version=1;
SET @u_marker='structure-c-20261019; baselineId=2026-10-07-delivery-261006-v8-v6; partial=92/99; NOT_PUBLISHED';
SET @u_ok=0, @u_verified=0;
-- 1. Read-only expected values. All 92 pre-change row fingerprints must match exactly.
SET @u_files = CONVERT(CONCAT(

) USING utf8mb4);
SET @u_sheets = CONVERT(CONCAT(
,

) USING utf8mb4);
SET @u_rows = CONVERT(CONCAT(
,
,
,
,
,
,
,
,
