,
0x5c227d5d7d222c225b322c335d225d5d
) USING utf8mb4);

-- 2. Lock exact template and descendants. SERIALIZABLE is transaction-local; no global setting changes.
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT tmplt_id,tmplt_stat_cd FROM tmd_mdl_inpttmpltm
WHERE tmplt_id=@u_tmplt OR mdl_spt_cd=@u_model ORDER BY tmplt_id FOR UPDATE;
SELECT inpt_file_id FROM tmd_mdl_inptfiled WHERE tmplt_id=@u_tmplt FOR UPDATE;
SELECT s.inpt_sht_id FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
WHERE f.tmplt_id=@u_tmplt FOR UPDATE;
SELECT b.inpt_tbl_id FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt FOR UPDATE;
SELECT case_id FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@u_tmplt FOR UPDATE;
SELECT drft_id FROM tmd_mdl_inptdrftm WHERE tmplt_id=@u_tmplt FOR UPDATE;
SET @u_root=(SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@u_tmplt
 AND BINARY mdl_spt_cd=BINARY @u_model AND tmplt_ver_no=@u_version AND tmplt_stat_cd='DRAFT'
 AND del_yn='N' AND aply_bgn_dtm IS NULL AND BINARY tmplt_expn=BINARY @u_marker);
SET @u_active=(SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@u_model AND tmplt_stat_cd='ACTIVE' AND del_yn='N');
SET @u_links=(SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@u_tmplt);
SET @u_drafts=(SELECT COUNT(*) FROM tmd_mdl_inptdrftm WHERE tmplt_id=@u_tmplt);
SET @u_file_count=(SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id=@u_tmplt);
SET @u_file_matches=(SELECT COUNT(*) FROM JSON_TABLE(@u_files,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',name VARCHAR(255) PATH '$[1]',ord INT PATH '$[2]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@u_tmplt AND BINARY f.mdl_file_cd=BINARY x.role
 WHERE BINARY f.file_nm=BINARY x.name AND f.file_ord=x.ord AND f.file_type_cd='XLSM'
 AND f.file_strt_hash_val IS NULL AND f.del_yn='N');
SET @u_sheet_count=(SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt);
SET @u_sheet_matches=(SELECT COUNT(*) FROM JSON_TABLE(@u_sheets,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',name VARCHAR(150) PATH '$[1]',ord INT PATH '$[2]',state VARCHAR(20) PATH '$[3]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@u_tmplt AND BINARY f.mdl_file_cd=BINARY x.role
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND BINARY s.sht_nm=BINARY x.name
 WHERE s.sht_ord=x.ord AND s.sht_stat_cd=x.state AND s.del_yn='N');
SET @u_table_count=(SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
 JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt);
SET @u_scope_count=(SELECT COUNT(*) FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id)
 JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt);
SET @u_table_matches=(SELECT COUNT(*) FROM JSON_TABLE(@u_rows,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',sheet VARCHAR(150) PATH '$[1]',name VARCHAR(100) PATH '$[2]',digest CHAR(64) PATH '$[3]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@u_tmplt AND BINARY f.mdl_file_cd=BINARY x.role
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND BINARY s.sht_nm=BINARY x.sheet
 JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id=s.inpt_sht_id AND BINARY b.inpt_tbl_nm=BINARY x.name
 WHERE b.del_yn='N' AND s.sht_stat_cd='VISIBLE' AND b.qry_json IS NOT NULL
 AND SHA2(CONCAT_WS(CHAR(31),b.inpt_tbl_nm,b.tbl_ord,b.tbl_bgn_row_no,b.tbl_end_row_no,b.tbl_bgn_col_no,b.tbl_end_col_no,
 b.hdr_bgn_row_no,b.hdr_end_row_no,b.data_bgn_row_no,b.row_add_psbl_yn,b.col_add_psbl_yn,b.inpt_tbl_expn,b.qry_json),256)=x.digest);
SET @u_ok=IF(BINARY DATABASE()=BINARY 'midb' AND @@SESSION.foreign_key_checks=1
 AND @u_tmplt=7 AND BINARY @u_model=BINARY 'DRAFT_C_STRUCTURE' AND @u_version=1
 AND CHAR_LENGTH(TRIM(@u_actor)) BETWEEN 1 AND 50
 AND @u_root=1 AND @u_active=0 AND @u_links=0 AND @u_drafts=0
 AND @u_file_count=4 AND @u_file_matches=4 AND @u_sheet_count=70 AND @u_sheet_matches=70
 AND @u_table_count=92 AND @u_table_matches=92 AND @u_scope_count=0,1,0);
SELECT @u_root AS root_must_be_1,@u_file_matches AS files_must_be_4,@u_sheet_matches AS sheets_must_be_70,
 @u_table_matches AS tables_must_be_92,@u_links AS links_must_be_0,@u_drafts AS drafts_must_be_0,
 @u_scope_count AS scopes_must_be_0,@u_ok AS precheck_must_be_1,
 IF(@u_ok=1,'PRECHECK_OK','STOP_AND_ROLLBACK') AS decision;
-- STOP_AND_ROLLBACK: ROLLBACK and stop. No mutations below are enabled unless the whole precheck passed.
-- Session-only before image. This is not a durable backup; retain a DB-client export before committed apply.
SET @u_before=(SELECT JSON_ARRAYAGG(JSON_OBJECT('id',b.inpt_tbl_id,'qry',b.qry_json))
 FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
 JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt);

-- 3. Apply only published-contract additions; retain all other JSON keys/values semantically.
UPDATE tmd_mdl_inpttbld b
JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
JOIN tmd_mdl_inpttmpltm t ON t.tmplt_id=f.tmplt_id
JOIN JSON_TABLE(@u_rows,'$[*]' COLUMNS(role VARCHAR(20) PATH '$[0]',sheet VARCHAR(150) PATH '$[1]',
 name VARCHAR(100) PATH '$[2]',validation_json LONGTEXT PATH '$[4]',header_json LONGTEXT PATH '$[5]')) x
 ON BINARY f.mdl_file_cd=BINARY x.role AND BINARY s.sht_nm=BINARY x.sheet AND BINARY b.inpt_tbl_nm=BINARY x.name
SET b.qry_json=JSON_SET(b.qry_json,'$.uploadValidation',CAST(x.validation_json AS JSON),'$.headerRows',CAST(x.header_json AS JSON)),
 b.mod_usr_logn_id=@u_actor,b.mod_dtm=CURRENT_TIMESTAMP
WHERE @u_ok=1 AND t.tmplt_id=@u_tmplt AND t.tmplt_stat_cd='DRAFT' AND t.del_yn='N';

-- 4. Verify full expected JSON, unchanged metadata, and exact 92-row coverage (not driver ROW_COUNT).
SET @u_after_matches=(SELECT COUNT(*) FROM JSON_TABLE(@u_rows,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',sheet VARCHAR(150) PATH '$[1]',name VARCHAR(100) PATH '$[2]',digest CHAR(64) PATH '$[3]',
 validation_json LONGTEXT PATH '$[4]',header_json LONGTEXT PATH '$[5]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@u_tmplt AND BINARY f.mdl_file_cd=BINARY x.role
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND BINARY s.sht_nm=BINARY x.sheet
 JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id=s.inpt_sht_id AND BINARY b.inpt_tbl_nm=BINARY x.name
 JOIN JSON_TABLE(@u_before,'$[*]' COLUMNS(id BIGINT PATH '$.id',qry LONGTEXT PATH '$.qry')) old ON old.id=b.inpt_tbl_id
 WHERE CAST(b.qry_json AS JSON)=JSON_SET(old.qry,'$.uploadValidation',CAST(x.validation_json AS JSON),'$.headerRows',CAST(x.header_json AS JSON))
 AND b.mod_usr_logn_id=@u_actor AND b.del_yn='N'
 AND SHA2(CONCAT_WS(CHAR(31),b.inpt_tbl_nm,b.tbl_ord,b.tbl_bgn_row_no,b.tbl_end_row_no,b.tbl_bgn_col_no,b.tbl_end_col_no,
 b.hdr_bgn_row_no,b.hdr_end_row_no,b.data_bgn_row_no,b.row_add_psbl_yn,b.col_add_psbl_yn,b.inpt_tbl_expn,old.qry),256)=x.digest);
SET @u_verified=IF(@u_ok=1 AND @u_after_matches=92,1,0);
SELECT @u_after_matches AS patched_tables_must_be_92,@u_verified AS verified_must_be_1,
 IF(@u_verified=1,'VERIFIED','STOP_AND_ROLLBACK') AS decision;
SELECT f.mdl_file_cd,COUNT(*) AS tables,
 SUM(JSON_LENGTH(JSON_EXTRACT(b.qry_json,'$.uploadValidation.headerCells'))) AS fixed_header_checks
FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@u_tmplt GROUP BY f.mdl_file_cd ORDER BY f.mdl_file_cd;
SELECT s.sht_nm,JSON_EXTRACT(b.qry_json,'$.headerRows') AS header_rows
FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id)
JOIN tmd_mdl_inptfiled f USING(inpt_file_id)
WHERE f.tmplt_id=@u_tmplt AND f.mdl_file_cd='SUPPLY' AND s.sht_nm IN ('LiqUtilAdjustment','LiqProdAdjustment');
SELECT tmplt_id,mdl_spt_cd,tmplt_ver_no,tmplt_stat_cd,aply_bgn_dtm FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@u_tmplt;
-- 5. Default rehearsal: leaves the DB unchanged. Commit is a separate, reviewed manual rerun.
-- No persistent before-image overwrite or destructive reverse migration is included.
ROLLBACK;

SELECT
    @u_ok AS precheck_must_be_1,
    @u_after_matches AS patched_tables_must_be_92,
    @u_verified AS verified_must_be_1;
